import json
import os
import re
import urllib.error
import urllib.request
from urllib.parse import urlparse

from lfx.custom.custom_component.component import Component
from lfx.io import IntInput, MessageTextInput, Output, StrInput
from lfx.schema.message import Message

ACTION_PATTERNS = {
    "APPROVE": re.compile(r"\b(approve[d]?|setuju|disetujui|setujui)\b", re.IGNORECASE),
    "REJECT": re.compile(r"\b(reject(?:ed)?|tolak|ditolak)\b", re.IGNORECASE),
    "EDIT": re.compile(r"\b(edit(?:ed)?|revisi)\b", re.IGNORECASE),
}
UUID = r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"
CASE_LABELED_RE = re.compile(r"(?:case|patient)[_\s-]*id\s*[:=]\s*([A-Za-z0-9][A-Za-z0-9_-]*)", re.IGNORECASE)
CASE_SHORT_RE = re.compile(r"\b(?:CASE-\d+|" + UUID + r"|P\d+)\b", re.IGNORECASE)
PHARM_LABELED_RE = re.compile(r"pharmacist[_\s-]*id\s*[:=]\s*([A-Za-z0-9][A-Za-z0-9_-]*)", re.IGNORECASE)
PHARM_SHORT_RE = re.compile(r"\bPHARM-\d+\b", re.IGNORECASE)
EDITED_RESULT_RE = re.compile(r"edited_result\s*[:=]\s*", re.IGNORECASE)
NOTE = "Keputusan farmasis telah dicatat dalam audit trail PrioMed-Rec."


def _to_text(value) -> str:
    if value is None:
        return ""
    text = getattr(value, "text", None)
    if isinstance(text, str):
        return text
    return str(value)


class PrioMedReviewClient(Component):
    display_name = "PrioMed-Rec Review Client"
    description = (
        "Parses the pharmacist action (APPROVE / REJECT / EDIT) from the chat message and records it via "
        "POST /review (audit trail). The action is parsed deterministically; if it is missing or ambiguous, "
        "nothing is sent."
    )
    documentation: str = ""
    icon = "Globe"
    name = "PrioMedReviewClient"

    inputs = [
        MessageTextInput(
            name="review_input",
            display_name="Pharmacist Review Input",
            info="Pharmacist message containing exactly one action: APPROVE, REJECT, or EDIT, plus an optional note.",
            required=True,
        ),
        StrInput(
            name="case_id",
            display_name="Patient / Case ID",
            info="Default case ID. Overridden if the message contains case_id: X, CASE-123, P123, or a UUID.",
            value="",
        ),
        StrInput(
            name="pharmacist_id",
            display_name="Pharmacist ID",
            info="Default pharmacist ID. Overridden if the message contains pharmacist_id: X or PHARM-123.",
            value="PHARM-001",
        ),
        StrInput(
            name="ai_result_json",
            display_name="AI Result (JSON object)",
            info="JSON object of the AI result being reviewed (sent as ai_result). Use {} if unavailable.",
            value="{}",
            advanced=True,
        ),
        StrInput(
            name="api_base_url",
            display_name="API Base URL",
            info="Base URL of the PrioMed-Rec FastAPI backend. If empty, env PRIOMEDREC_API_URL or http://localhost:8000 is used.",
            value="http://localhost:8000",
        ),
        StrInput(
            name="endpoint_path",
            display_name="Endpoint Path",
            info="Path of the review endpoint (POST).",
            value="/review",
            advanced=True,
        ),
        IntInput(
            name="timeout",
            display_name="Timeout (seconds)",
            info="HTTP timeout for the API call.",
            value=30,
            advanced=True,
        ),
    ]

    outputs = [
        Output(display_name="Review Confirmation", name="confirmation", method="record_review"),
    ]

    def _reply(self, text: str) -> Message:
        self.status = text
        return Message(text=text)

    def _fail(self, title: str, detail: str) -> Message:
        return self._reply(
            "⚠️ Review BELUM tercatat\n"
            f"- Alasan: {title}\n"
            f"- Detail: {detail}\n\n"
            "Tidak ada keputusan yang disimpan. Silakan perbaiki input dan kirim ulang."
        )

    def _parse_action(self, text: str):
        found = [action for action, pattern in ACTION_PATTERNS.items() if pattern.search(text)]
        if len(found) == 1:
            return found[0], None
        if not found:
            return None, "Aksi tidak ditemukan. Gunakan salah satu: APPROVE, REJECT, atau EDIT."
        return None, "Aksi ambigu (" + ", ".join(found) + "). Gunakan hanya satu aksi per pesan."

    def _parse_edited_result(self, text: str):
        match = EDITED_RESULT_RE.search(text)
        if not match:
            return None, None
        try:
            value, _ = json.JSONDecoder().raw_decode(text[match.end():].lstrip())
        except json.JSONDecodeError:
            return None, "edited_result harus berupa JSON valid."
        return value, None

    def record_review(self) -> Message:
        text = _to_text(self.review_input).strip()
        if not text:
            return self._fail("Input kosong", "Tuliskan aksi (APPROVE/REJECT/EDIT) dan catatan farmasis.")

        action, action_error = self._parse_action(text)
        if action_error:
            return self._fail("Aksi tidak valid", action_error)

        case_match = CASE_LABELED_RE.search(text) or CASE_SHORT_RE.search(text)
        case_id = (case_match.group(1) if case_match and case_match.groups() else case_match.group(0) if case_match else "") or _to_text(self.case_id).strip()
        if not case_id:
            return self._fail("Case ID tidak ditemukan", "Isi field Patient / Case ID atau tulis case_id: P001 pada pesan.")

        pharm_match = PHARM_LABELED_RE.search(text) or PHARM_SHORT_RE.search(text)
        pharmacist_id = (pharm_match.group(1) if pharm_match and pharm_match.groups() else pharm_match.group(0) if pharm_match else "") or _to_text(self.pharmacist_id).strip()
        if not pharmacist_id:
            return self._fail("Pharmacist ID tidak ditemukan", "Isi field Pharmacist ID atau tulis pharmacist_id: PHARM-001.")

        try:
            ai_result = json.loads(_to_text(self.ai_result_json).strip() or "{}")
        except json.JSONDecodeError:
            return self._fail("AI Result tidak valid", "Field AI Result harus berupa JSON object, mis. {}.")
        if not isinstance(ai_result, dict):
            return self._fail("AI Result tidak valid", "Field AI Result harus berupa JSON object, mis. {}.")

        payload = {
            "case_id": case_id,
            "pharmacist_id": pharmacist_id,
            "ai_result": ai_result,
            "action": action,
            "pharmacist_note": text,
        }
        if action == "EDIT":
            edited, edit_error = self._parse_edited_result(text)
            if edit_error:
                return self._fail("edited_result tidak valid", edit_error)
            if edited is not None:
                payload["edited_result"] = edited

        base = (_to_text(self.api_base_url).strip() or os.environ.get("PRIOMEDREC_API_URL", "").strip() or "http://localhost:8000")
        path = _to_text(self.endpoint_path).strip() or "/review"
        url = base.rstrip("/") + "/" + path.lstrip("/")
        if urlparse(url).scheme not in ("http", "https"):
            return self._fail("URL tidak valid", "API Base URL harus diawali http:// atau https://")

        try:
            timeout = int(self.timeout) if self.timeout else 30
        except (TypeError, ValueError):
            timeout = 30

        request = urllib.request.Request(
            url,
            data=json.dumps(payload).encode("utf-8"),
            headers={"Content-Type": "application/json", "Accept": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:  # noqa: S310 (scheme validated above)
                raw = response.read().decode("utf-8", errors="replace")
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")[:500]
            return self._fail(f"API mengembalikan HTTP {exc.code}", detail or "tanpa detail")
        except Exception as exc:  # noqa: BLE001
            return self._fail("Tidak dapat menghubungi API", f"{str(exc)[:300]} (endpoint: {url})")

        try:
            result = json.loads(raw)
        except json.JSONDecodeError:
            return self._fail("Respons API bukan JSON valid", raw[:300])
        if not isinstance(result, dict):
            return self._fail("Respons API tidak sesuai format", raw[:300])

        review_id = result.get("review_id")
        timestamp = next((result[k] for k in ("timestamp", "reviewed_at", "created_at") if result.get(k)), None)
        if not review_id:
            return self._fail("Respons API tidak memuat review_id", json.dumps(result, ensure_ascii=False)[:300])

        return self._reply(
            "✅ Review Tercatat\n"
            f"- Aksi: {action}\n"
            f"- Case ID: {case_id}\n"
            f"- Pharmacist: {pharmacist_id}\n"
            f"- Review ID: {review_id}\n"
            f"- Timestamp: {timestamp if timestamp else 'tidak disediakan oleh API'}\n\n"
            f"{NOTE}"
        )
